# @generated by:gauntlet run:godseye-hermes-setup
"""Opt-in real pinned Hermes configuration/skills qualification without model calls."""

import importlib.util
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import unittest

sys.dont_write_bytecode = True
REPO = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(REPO / "scripts"))
import hermes_profiles as PROFILES

SPEC = importlib.util.spec_from_file_location("hermes_installer", REPO / "scripts/install-hermes.py")
INSTALLER = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(INSTALLER)


class RealHermes(unittest.TestCase):
    def test_generated_profiles_resolve_only_pinned_skills_and_zero_tools(self) -> None:
        tool = INSTALLER.resolve_root(str(REPO), False)
        INSTALLER.verify_install(tool)
        previous_umask = os.umask(0o077)
        try:
            with tempfile.TemporaryDirectory(prefix="godseye-hermes-native-") as directory:
                root = Path(directory).resolve()
                profiles = root / "profiles"
                profiles.mkdir(mode=0o700)
                for role in ("operations", "security", "research-marketing"):
                    record = PROFILES.prepare(profiles, REPO, {
                        "projectId": "11111111-1111-4111-8111-111111111111",
                        "environmentId": "22222222-2222-4222-8222-222222222222", "role": role,
                    })
                    os_home = root / ("home-" + role)
                    os_home.mkdir(mode=0o700)
                    # A prepared immutable recipe is not a live Hermes state directory.
                    # Upstream writes auth locks/config backups even during read-only imports.
                    probe_home = root / ("probe-" + role)
                    shutil.copytree(Path(record["home"]), probe_home)
                    environment = INSTALLER.child_environment(tool)
                    environment.update({
                        "HOME": str(os_home), "HERMES_HOME": str(probe_home),
                        "HERMES_DISABLE_LAZY_INSTALLS": "1",
                        "HERMES_INSTALL_ROOT": str(tool / "identity"),
                    })
                    program = """
import json,socket
def refuse(*args,**kwargs):
    raise AssertionError('Native Hermes qualification forbids network access')
socket.socket.connect=refuse
socket.socket.connect_ex=refuse
socket.socket.sendto=refuse
socket.create_connection=refuse
socket.getaddrinfo=refuse
from hermes_cli.config import load_config
from hermes_cli.tools_config import _get_platform_tools
from tools.skills_tool import find_all_skills
config=load_config()
cli=_get_platform_tools(config,'cli')
api=_get_platform_tools(config,'api_server')
skills=find_all_skills()
names=sorted(item['name'] for item in skills)
assert cli == set(), 'CLI tools were enabled'
assert api == set(), 'API tools were enabled'
assert names == ['godseye-context'], 'Unreviewed skills were visible'
assert config['model']['provider'] == 'openai'
assert config['model']['default'] == 'UNCONFIGURED'
assert config['curator']['enabled'] is False
assert config['skills']['project_discovery'] is False
assert config['skills']['external_dirs'] == []
assert config['memory']['memory_enabled'] is False
assert config['memory']['user_profile_enabled'] is False
assert config['mcp_servers'] == {}
print(json.dumps({'skills':names,'cliTools':len(cli),'apiTools':len(api),'network':'denied','modelCalls':0}))
"""
                    result = subprocess.run(
                        [str(tool / "venv/bin/python"), "-B", "-c", program],
                        cwd=tool / "source", env=environment, capture_output=True,
                        text=True, timeout=60, check=False,
                    )
                    self.assertEqual(result.returncode, 0, f"Role {role}: {result.stderr[-4000:]}")
                    evidence = json.loads(result.stdout.strip().splitlines()[-1])
                    self.assertEqual(evidence, {
                        "skills": ["godseye-context"], "cliTools": 0, "apiTools": 0,
                        "network": "denied", "modelCalls": 0,
                    })
                    manifest = json.loads((Path(record["home"]) / "snapshot.json").read_bytes())
                    for name in manifest["files"]:
                        self.assertEqual((probe_home / name).read_bytes(), (Path(record["home"]) / name).read_bytes())
                    retained = PROFILES.inspect(profiles, REPO, {"profileId": record["profileId"]})
                    self.assertEqual(retained["revision"], record["revision"])
                    self.assertFalse(retained["runEnabled"])
        finally:
            os.umask(previous_umask)
        INSTALLER.verify_install(tool)


if __name__ == "__main__":
    unittest.main(verbosity=2)
